/** Project identity. Generated by Forge at scaffold time; safe to edit. */
export const site = {
  name: "{{projectName}}",
  slug: "{{projectSlug}}",
  description: "{{projectName}}, built with Next.js.",
  locale: "en",
  /** Public origin used for canonical URLs, sitemap and Open Graph. */
  url: process.env.NEXT_PUBLIC_SITE_URL ?? "http://localhost:3000",
} as const;

/** Absolute URL for a path on this site (canonical links, sitemaps, emails). */
export function absoluteUrl(path = "/", base: string = site.url): string {
  return new URL(path, base.endsWith("/") ? base : `${base}/`).toString();
}
